using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using FishingDesktop.GameCore;

static class FloatEquipmentOffersTests
{
    static int passed,failed;
    static void Need(bool value,string why){if(!value)throw new Exception(why);}
    static void Throws<T>(Action action)where T:Exception{try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception error){failed++;Console.WriteLine("FAIL "+name+": "+error);}}
    static bool Same(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
    static FloatEquipmentCatalog Catalog(bool reverse=false,int change=0)
    {
        string bait=change==2?"maggot":"worm";int diameter=change==4?181:180;
        var defs=new List<FloatEquipmentDefinition>{
            new FloatEquipmentDefinition("rod",FloatEquipmentKind.Rod,150000,0,change==5?1001:1000,change==6?25001:25000),
            new FloatEquipmentDefinition("reel",FloatEquipmentKind.Reel,200000),
            new FloatEquipmentDefinition("line",FloatEquipmentKind.Line,0,diameter),
            new FloatEquipmentDefinition("hook",FloatEquipmentKind.Hook,change==3?201:200),
            new FloatEquipmentDefinition("float",FloatEquipmentKind.Bobber,3000,0,2000,change==7?3001:3000),
            new FloatEquipmentDefinition("sinker",FloatEquipmentKind.Sinker,2500),
            new FloatEquipmentDefinition("spare-hook",FloatEquipmentKind.Hook,250),
            new FloatEquipmentDefinition("unused-reel",FloatEquipmentKind.Reel,change==13?180001:180000)};
        var pairs=new List<FloatEquipmentPairRule>{new FloatEquipmentPairRule("rod","reel",change!=8),new FloatEquipmentPairRule("rod","unused-reel",true)};
        var spools=new List<FloatEquipmentSpoolRule>{new FloatEquipmentSpoolRule("reel","line",diameter,change==9?50001:50000),new FloatEquipmentSpoolRule("unused-reel","line",diameter,75000)};
        var hooks=new List<FloatEquipmentPairRule>{new FloatEquipmentPairRule("hook",bait,change!=10),new FloatEquipmentPairRule("spare-hook",bait,true)};
        var losses=new List<FloatEquipmentLossRule>{new FloatEquipmentLossRule("main",change==11?new[]{FloatEquipmentSlot.Hook,FloatEquipmentSlot.Bobber}:new[]{FloatEquipmentSlot.Hook,FloatEquipmentSlot.Bobber,FloatEquipmentSlot.Sinker}),new FloatEquipmentLossRule(change==12?"other-hook":"hook-only",new[]{FloatEquipmentSlot.Hook})};
        if(reverse){defs.Reverse();pairs.Reverse();spools.Reverse();hooks.Reverse();losses.Reverse();}
        return new FloatEquipmentCatalog(change==1?2:1,bait,defs,pairs,spools,hooks,losses);
    }
    static FloatEquipmentOffer[] Rows()
    {return new[]{new FloatEquipmentOffer("hook-single","hook",FloatEquipmentKind.Hook,20),new FloatEquipmentOffer("float-single","float",FloatEquipmentKind.Bobber,80),new FloatEquipmentOffer("sinker-single","sinker",FloatEquipmentKind.Sinker,20),new FloatEquipmentOffer("line-50m","line",FloatEquipmentKind.Line,100,50000)};}
    static FloatEquipmentOffers Offers(FloatEquipmentCatalog catalog=null,IEnumerable<FloatEquipmentOffer> rows=null,long maximum=1000000,long version=1)
    {return new FloatEquipmentOffers(version,catalog??Catalog(),rows??Rows(),maximum);}
    static void Key(BinaryWriter writer,string text){var bytes=new UTF8Encoding(false,true).GetBytes(text);writer.Write((ushort)bytes.Length);writer.Write(bytes);}
    static byte[] UncheckedPayload(FloatEquipmentCatalog equipment,IEnumerable<FloatEquipmentOffer> rows,long version=1)
    {
        var list=new List<FloatEquipmentOffer>(rows);using(var memory=new MemoryStream()){using(var writer=new BinaryWriter(memory,Encoding.UTF8,true)){
            writer.Write(new byte[]{70,69,79,83});writer.Write((ushort)1);writer.Write(version);writer.Write(equipment.Version);
            string signature=FloatEquipmentOffersCodec.EquipmentSignature(equipment);for(int i=0;i<signature.Length;i+=2)writer.Write(Convert.ToByte(signature.Substring(i,2),16));writer.Write((ushort)list.Count);
            foreach(var row in list){Key(writer,row.Sku);Key(writer,row.DefinitionKey);writer.Write((byte)row.Kind);writer.Write(row.PriceMinor);writer.Write(row.LineLengthMm);}
        }return memory.ToArray();}
    }
    static int KindOffset(byte[] payload){using(var memory=new MemoryStream(payload))using(var reader=new BinaryReader(memory)){memory.Position=56;memory.Position+=2+reader.ReadUInt16();memory.Position+=2+reader.ReadUInt16();return (int)memory.Position;}}
    static byte[] Changed(byte[] original,int offset,params byte[] replacement){var copy=(byte[])original.Clone();Array.Copy(replacement,0,copy,offset,replacement.Length);return copy;}
    static FloatEquipmentCatalog LargeCatalog()
    {
        var definitions=new List<FloatEquipmentDefinition>();var rods=new List<string>();var reels=new List<string>();var lines=new List<string>();var pairs=new List<FloatEquipmentPairRule>();var spools=new List<FloatEquipmentSpoolRule>();var losses=new List<FloatEquipmentLossRule>();
        for(int i=0;i<16;i++){
            string suffix=i.ToString("d2")+new string('x',90);string rod="rod-"+suffix,reel="reel"+suffix,line="line"+suffix;rods.Add(rod);reels.Add(reel);lines.Add(line);
            definitions.Add(new FloatEquipmentDefinition(rod,FloatEquipmentKind.Rod,10000,0,1,10000));definitions.Add(new FloatEquipmentDefinition(reel,FloatEquipmentKind.Reel,10000));definitions.Add(new FloatEquipmentDefinition(line,FloatEquipmentKind.Line,0,180));
        }
        definitions.Add(new FloatEquipmentDefinition("hook",FloatEquipmentKind.Hook,100));
        for(int i=0;i<16;i++)for(int j=0;j<8;j++){pairs.Add(new FloatEquipmentPairRule(rods[i],reels[j],true));spools.Add(new FloatEquipmentSpoolRule(reels[i],lines[j],180,50000));}
        for(int i=0;i<128;i++)losses.Add(new FloatEquipmentLossRule(i.ToString("d3")+new string('x',93),new[]{FloatEquipmentSlot.Hook}));
        return new FloatEquipmentCatalog(1,"worm",definitions,pairs,spools,new[]{new FloatEquipmentPairRule("hook","worm",true)},losses);
    }
    static int Main()
    {
        Test("four explicitly priced categories bind without creating owned items",()=>{var equipment=Catalog();var offers=Offers(equipment);Need(offers.Offers.Count==4&&offers.Version==1&&offers.EquipmentCatalogVersion==1&&Object.ReferenceEquals(offers.BoundEquipmentCatalog,equipment),"Binding changed.");foreach(var row in offers.Offers)Need(row.Units==1,"An offer changed quantity.");Need(offers.Find("line-50m").LineLengthMm==50000,"Whole segment length missing.");});
        Test("source and exposed collections cannot mutate frozen offers",()=>{var source=new List<FloatEquipmentOffer>(Rows());var offers=Offers(rows:source);string signature=offers.Signature;source.Clear();Need(offers.Offers.Count==4&&offers.Signature==signature,"Source mutation changed catalogue.");Throws<NotSupportedException>(()=>((IList<FloatEquipmentOffer>)offers.Offers).Clear());});
        Test("unknown rod and reel offers are not allowed",()=>{foreach(var kind in new[]{FloatEquipmentKind.Rod,FloatEquipmentKind.Reel,(FloatEquipmentKind)255,(FloatEquipmentKind)(-1)})Throws<ArgumentOutOfRangeException>(()=>new FloatEquipmentOffer("sku","hook",kind,1));});
        Test("SKU and definition keys use bounded canonical identifiers",()=>{foreach(string key in new[]{null,"","UPPER","with space","中文",new string('x',97)}){Throws<ArgumentException>(()=>new FloatEquipmentOffer(key,"hook",FloatEquipmentKind.Hook,1));Throws<ArgumentException>(()=>new FloatEquipmentOffer("sku",key,FloatEquipmentKind.Hook,1));}Need(new FloatEquipmentOffer(new string('x',96),"hook",FloatEquipmentKind.Hook,1).Sku.Length==96,"Maximum key rejected.");});
        Test("nonpositive prices and wallet limits are rejected",()=>{foreach(long price in new[]{0L,-1L,Int64.MinValue})Throws<ArgumentOutOfRangeException>(()=>new FloatEquipmentOffer("sku","hook",FloatEquipmentKind.Hook,price));foreach(long wallet in new[]{0L,-1L})Throws<ArgumentOutOfRangeException>(()=>Offers(maximum:wallet));});
        Test("price boundaries remain exact Int64 and revalidate against caller wallet",()=>{var rows=new[]{new FloatEquipmentOffer("sku","hook",FloatEquipmentKind.Hook,Int64.MaxValue)};var offers=Offers(rows:rows,maximum:Int64.MaxValue);Need(offers.Offers[0].PriceMinor==Int64.MaxValue,"Price rounded.");Throws<ArgumentException>(()=>offers.ValidateAgainst(Catalog(),Int64.MaxValue-1));Throws<ArgumentException>(()=>Offers(rows:rows,maximum:1000000));});
        Test("line requires an explicit bounded whole segment and other items have no length",()=>{foreach(long length in new[]{0L,-1L,100000001L})Throws<ArgumentOutOfRangeException>(()=>new FloatEquipmentOffer("sku","line",FloatEquipmentKind.Line,1,length));foreach(var kind in new[]{FloatEquipmentKind.Hook,FloatEquipmentKind.Bobber,FloatEquipmentKind.Sinker})Throws<ArgumentException>(()=>new FloatEquipmentOffer("sku","hook",kind,1,1));Need(new FloatEquipmentOffer("min","line",FloatEquipmentKind.Line,1,1).LineLengthMm==1&&new FloatEquipmentOffer("max","line",FloatEquipmentKind.Line,1,100000000).LineLengthMm==100000000,"Line boundary changed.");});
        Test("null missing and wrong-kind definitions never get inferred",()=>{Throws<ArgumentNullException>(()=>new FloatEquipmentOffers(1,null,Rows(),1000000));Throws<ArgumentNullException>(()=>new FloatEquipmentOffers(1,Catalog(),null,1000000));Throws<ArgumentException>(()=>Offers(rows:new[]{new FloatEquipmentOffer("sku","missing",FloatEquipmentKind.Hook,1)}));Throws<ArgumentException>(()=>Offers(rows:new[]{new FloatEquipmentOffer("sku","reel",FloatEquipmentKind.Hook,1)}));});
        Test("empty null duplicate and excessive SKU collections reject",()=>{Throws<ArgumentException>(()=>Offers(rows:new FloatEquipmentOffer[0]));Throws<ArgumentException>(()=>Offers(rows:new FloatEquipmentOffer[]{null}));var row=Rows()[0];Throws<ArgumentException>(()=>Offers(rows:new[]{row,row}));var list=new List<FloatEquipmentOffer>();for(int i=0;i<17;i++)list.Add(new FloatEquipmentOffer("sku-"+i,"hook",FloatEquipmentKind.Hook,1));Throws<ArgumentException>(()=>Offers(rows:list));});
        Test("maximum sixteen explicit SKUs and independent lookup work",()=>{var rows=new List<FloatEquipmentOffer>();for(int i=0;i<16;i++)rows.Add(new FloatEquipmentOffer("sku-"+i,"hook",FloatEquipmentKind.Hook,i+1));var offers=Offers(rows:rows);Need(offers.Offers.Count==16&&offers.Find("sku-0").PriceMinor==1&&offers.Find("SKU-0")==null&&offers.Find(null)==null,"Bounded lookup changed.");});
        Test("separate equal catalogues and reversed source collections have same complete identity",()=>{var first=Offers();var rows=new List<FloatEquipmentOffer>(Rows());rows.Reverse();var second=Offers(Catalog(true),rows);Need(first.Signature==second.Signature&&first.EquipmentCatalogSignature==second.EquipmentCatalogSignature&&Same(FloatEquipmentOffersCodec.Encode(first),FloatEquipmentOffersCodec.Encode(second)),"Canonical order changed identity.");first.ValidateAgainst(Catalog(true),1000000);});
        Test("all equipment definitions relations and loss rules affect the binding",()=>{var original=Offers();for(int change=1;change<=13;change++){var other=Catalog(change:change);Need(FloatEquipmentOffersCodec.EquipmentSignature(other)!=original.EquipmentCatalogSignature,"Omitted equipment change "+change);Throws<ArgumentException>(()=>original.ValidateAgainst(other,1000000));}});
        Test("offer version SKU definition price and line length affect content identity",()=>{var original=Offers();Need(original.Signature!=Offers(version:2).Signature,"Version absent.");for(int variant=0;variant<4;variant++){var rows=new List<FloatEquipmentOffer>(Rows());rows[0]=variant==0?new FloatEquipmentOffer("changed-sku","hook",FloatEquipmentKind.Hook,20):variant==1?new FloatEquipmentOffer("hook-single","spare-hook",FloatEquipmentKind.Hook,20):variant==2?new FloatEquipmentOffer("hook-single","hook",FloatEquipmentKind.Hook,21):rows[0];if(variant==3)rows[3]=new FloatEquipmentOffer("line-50m","line",FloatEquipmentKind.Line,100,49999);Need(Offers(rows:rows).Signature!=original.Signature,"Omitted offer field "+variant);}});
        Test("wallet maximum validates prices without silently changing a price identity",()=>{var a=Offers(maximum:1000);var b=Offers(maximum:1000000);Need(a.Signature==b.Signature&&Same(FloatEquipmentOffersCodec.Encode(a),FloatEquipmentOffersCodec.Encode(b)),"Wallet policy was mixed into product prices.");});
        Test("codec roundtrip returns equivalent immutable bound catalogue",()=>{var catalog=Catalog();var original=Offers(catalog);var bytes=FloatEquipmentOffersCodec.Encode(original);var decoded=FloatEquipmentOffersCodec.Decode(bytes,Catalog(true),1000000);Need(decoded.Signature==original.Signature&&Same(bytes,FloatEquipmentOffersCodec.Encode(decoded))&&decoded.Find("line-50m").LineLengthMm==50000,"Roundtrip changed catalogue.");});
        Test("independently assembled payload equals canonical output",()=>{var equipment=Catalog();var offers=Offers(equipment);Need(Same(UncheckedPayload(equipment,offers.Offers),FloatEquipmentOffersCodec.Encode(offers)),"Documented little endian payload differs.");var bytes=FloatEquipmentOffersCodec.Encode(Offers(version:0x0102030405060708L));Need(bytes[0]==70&&bytes[3]==83&&bytes[4]==1&&bytes[5]==0&&bytes[6]==8&&bytes[13]==1&&bytes[54]==4&&bytes[55]==0,"Header or fixed integer byte order changed.");});
        Test("FECS and FEOS v1 golden identities match an independent byte assembly",()=>{
            var equipment=new FloatEquipmentCatalog(1,"worm",new[]{new FloatEquipmentDefinition("hook",FloatEquipmentKind.Hook,200)},new FloatEquipmentPairRule[0],new FloatEquipmentSpoolRule[0],new[]{new FloatEquipmentPairRule("hook","worm",true)},new[]{new FloatEquipmentLossRule("hook",new[]{FloatEquipmentSlot.Hook})});
            var offers=Offers(equipment,new[]{new FloatEquipmentOffer("hook-single","hook",FloatEquipmentKind.Hook,20)});
            // Generated from the specified fields by a separate Node Buffer
            // writer, not by either production codec or its C# test writer.
            const string payload="46454f530100010000000000000001000000000000007eeabc697f63f2d701676029d172a989cb733b8e6d93a8490315f20e8defd7dd01000b00686f6f6b2d73696e676c650400686f6f6b0314000000000000000000000000000000";
            Need(offers.EquipmentCatalogSignature=="7eeabc697f63f2d701676029d172a989cb733b8e6d93a8490315f20e8defd7dd"&&offers.Signature=="d9844eb582944960fc154fdf0fc14efef699cfb70874fdecb905ad44e5ce056c"&&BitConverter.ToString(FloatEquipmentOffersCodec.Encode(offers)).Replace("-","").ToLowerInvariant()==payload,"V1 golden identity changed.");
        });
        Test("every strict prefix truncation is rejected",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));for(int n=0;n<bytes.Length;n++){var prefix=new byte[n];Array.Copy(bytes,prefix,n);Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(prefix,equipment,1000000));}});
        Test("null oversized and trailing payloads are rejected",()=>{var equipment=Catalog();Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(null,equipment,1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(new byte[65537],equipment,1000000));var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));foreach(int length in new[]{bytes.Length+1,65536}){var tail=new byte[length];Array.Copy(bytes,tail,bytes.Length);Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(tail,equipment,1000000));}});
        Test("magic format and positive catalogue versions are strict",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));foreach(byte[] invalid in new[]{Changed(bytes,0,0),Changed(bytes,4,2),Changed(bytes,6,0,0,0,0,0,0,0,0)})Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(invalid,equipment,1000000));Throws<ArgumentOutOfRangeException>(()=>Offers(version:0));});
        Test("decode requires the caller's actual existing catalogue and wallet bound",()=>{var bytes=FloatEquipmentOffersCodec.Encode(Offers());Throws<ArgumentNullException>(()=>FloatEquipmentOffersCodec.Decode(bytes,null,1000000));Throws<ArgumentOutOfRangeException>(()=>FloatEquipmentOffersCodec.Decode(bytes,Catalog(),0));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(bytes,Catalog(change:3),1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(bytes,Catalog(),79));});
        Test("serialized equipment version and full content signature cannot be substituted",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,14,2),equipment,1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,22,(byte)(bytes[22]^1)),equipment,1000000));});
        Test("unknown kinds impossible prices and illegal lengths reject in codec",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));int kind=KindOffset(bytes);foreach(byte value in new byte[]{0,1,255})Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,kind,value),equipment,1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,kind+1,0,0,0,0,0,0,0,0),equipment,1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,kind+9,1),equipment,1000000));});
        Test("empty excessive and lying counts cannot consume arbitrary rows",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));foreach(byte count in new byte[]{0,1,5,17,255})Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(Changed(bytes,54,count),equipment,1000000));});
        Test("noncanonical order and duplicate SKU payloads are rejected rather than sorted",()=>{var equipment=Catalog();var rows=new List<FloatEquipmentOffer>(Offers(equipment).Offers);rows.Reverse();Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(UncheckedPayload(equipment,rows),equipment,1000000));Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(UncheckedPayload(equipment,new[]{Rows()[0],Rows()[0]}),equipment,1000000));});
        Test("strict UTF8 bounded key lengths and canonical characters reject",()=>{var equipment=Catalog();var bytes=FloatEquipmentOffersCodec.Encode(Offers(equipment));foreach(byte[] invalid in new[]{Changed(bytes,56,0,0),Changed(bytes,56,97,0),Changed(bytes,58,255),Changed(bytes,58,(byte)'A'),Changed(bytes,58,0)})Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(invalid,equipment,1000000));});
        Test("decoded offers cannot reference a missing or mismatched existing type",()=>{var equipment=Catalog();foreach(var row in new[]{new FloatEquipmentOffer("sku","missing",FloatEquipmentKind.Hook,1),new FloatEquipmentOffer("sku","reel",FloatEquipmentKind.Hook,1)})Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.Decode(UncheckedPayload(equipment,new[]{row}),equipment,1000000));});
        Test("maximum key count price and line limits roundtrip exactly",()=>{string key=new string('x',96);var equipment=new FloatEquipmentCatalog(1,"worm",new[]{new FloatEquipmentDefinition(key,FloatEquipmentKind.Line,0,180)},new FloatEquipmentPairRule[0],new FloatEquipmentSpoolRule[0],new FloatEquipmentPairRule[0],new FloatEquipmentLossRule[0]);var rows=new List<FloatEquipmentOffer>();for(int i=0;i<16;i++)rows.Add(new FloatEquipmentOffer(i.ToString("d2")+new string('s',94),key,FloatEquipmentKind.Line,Int64.MaxValue,100000000));var original=Offers(equipment,rows,Int64.MaxValue);var bytes=FloatEquipmentOffersCodec.Encode(original);var decoded=FloatEquipmentOffersCodec.Decode(bytes,equipment,Int64.MaxValue);Need(decoded.Offers.Count==16&&decoded.Offers[0].PriceMinor==Int64.MaxValue&&decoded.Offers[0].LineLengthMm==100000000&&bytes.Length<65536,"Boundary was rounded or overflowed.");});
        Test("returned bytes are independent and caller mutations cannot alter catalogue",()=>{var original=Offers();string signature=original.Signature;var bytes=FloatEquipmentOffersCodec.Encode(original);var pristine=(byte[])bytes.Clone();bytes[0]=0;Need(original.Signature==signature&&Same(pristine,FloatEquipmentOffersCodec.Encode(original)),"Output buffer mutated immutable content.");});
        Test("valid scalar edits change identity and are not claimed to be checksum failures",()=>{var equipment=Catalog();var original=Offers(equipment);var bytes=FloatEquipmentOffersCodec.Encode(original);int price=KindOffset(bytes)+1;var edited=Changed(bytes,price,(byte)(bytes[price]+1));var decoded=FloatEquipmentOffersCodec.Decode(edited,equipment,1000000);Need(decoded.Signature!=original.Signature&&Same(edited,FloatEquipmentOffersCodec.Encode(decoded)),"Valid changed data was not assigned its own identity.");});
        Test("bounded equipment identity refuses an oversized source manifest",()=>{Throws<InvalidDataException>(()=>FloatEquipmentOffersCodec.EquipmentSignature(LargeCatalog()));});
        Test("mutation sweep either rejects or roundtrips canonical bounded data",()=>{var equipment=Catalog();var original=FloatEquipmentOffersCodec.Encode(Offers(equipment));var random=new Random(3901);for(int i=0;i<1200;i++){var bytes=(byte[])original.Clone();bytes[random.Next(bytes.Length)]^=(byte)random.Next(1,256);try{var decoded=FloatEquipmentOffersCodec.Decode(bytes,equipment,1000000);Need(Same(bytes,FloatEquipmentOffersCodec.Encode(decoded)),"Accepted noncanonical bytes.");decoded.ValidateAgainst(equipment,1000000);}catch(InvalidDataException){}}});
        Console.WriteLine("RESULT "+passed+" passed "+failed+" failed");return failed==0?0:1;
    }
}
